#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int main()
{
    int n;
    cin >> n;

    string str;
    cin >> str;

    for (int i = 0; i < static_cast<int>(str.length()); i++) {
        for (int j = i + 1; j < static_cast<int>(str.length()); j++) {
            if (str[i] == '0' && str[j] == '1')
                swap(str[i], str[j]);
        }
    }

    int cnt = 0;
    for (int i = 0; i < static_cast<int>(str.length()); i++) {
        if (str[i] == '1')
            cnt++;
    }

    for (int i = cnt - 1; i < static_cast<int>(str.length()); i++)
        cout << str[i];

    return 0;
}

